def list_users_sorted(sort: str = "id", order: str = "asc") -> list[dict]:
    """Return every user ordered by ``sort`` in the given ``order`` direction.

    ``sort`` and ``order`` are validated against fixed allow-lists, so no
    request value is ever interpolated into SQL.
    """
    if sort not in SORT_FIELDS or order not in ORDER_VALUES:
        return []
    return sorted(store.list_all(), key=lambda user: user[sort], reverse=(order == "desc"))

